import { applyVisitCommand, createVisit, publicVisit } from "./visit-state.mjs";
import { sealVisit, unsealVisit } from "./visit-vault.mjs";
import { encodeRequest, decodeRequest } from "./visit-request.mjs";
import { syncActionMessages } from './action-chat.mjs';
import {clientCanWrite,electedPMSAuthority} from './gm-authority.mjs';
import {syncSoulTokens} from './soul-token.mjs';
import {foodInventoryUpdates} from './food-inventory.mjs';
import {assertCaseAvailable} from './case-lifecycle.mjs';
const NS = "pms";
const kind = doc => doc.getFlag(NS, "kind");
// Uniform dice are generated by the elected GM, never accepted from player payloads.
function randomDie() { const bytes = new Uint8Array(1); do { crypto.getRandomValues(bytes); } while (bytes[0] >= 252); return bytes[0] % 6 + 1; }

export class VisitService {
  constructor() { this.listeners = new Set(); this.pending = new Map(); this.queue = Promise.resolve(); this.localQueue = Promise.resolve(); this.privateDocument = null; this.canonical = null; }
  get authority() { return electedPMSAuthority(game.users,game.journal); }
  get isAuthority() { return this.authority?.id === game.user.id && clientCanWrite(); }
  get document() { return game.journal.find(d => kind(d) === "visitProjection"); }
  get state() { return this.document?.getFlag(NS, "visit") ?? null; }
  get privateState() { return game.user.isGM&&(this.isAuthority||this.canonical?.id===this.state?.id) ? this.canonical : null; }
  onChange(fn) { this.listeners.add(fn); return () => this.listeners.delete(fn); }
  notify() {
    for (const [id, p] of this.pending) {
      const r = this.state?.receipts.find(r => r.key === `${game.user.id}:${id}`);
      if (r) { clearTimeout(p.timer); this.pending.delete(id); r.ok ? p.resolve(r) : p.reject(new Error(r.message)); }
    }
    for (const fn of this.listeners) fn();
  }
  async loadPrivate({readOnly=!this.isAuthority}={}) {
    const id = this.state?.id;
    let privateDocument = game.journal.find(d => kind(d) === "visitVault" && d.getFlag(NS, "visitId") === id) ?? null;
    // Bridge the unreleased sandbox's encrypted pack into the regular document transport.
    // Pack reads were unrestricted and its update notifications broke on player clients in v14.368.
    const oldPack = game.packs.get("world.pms-control");
    if (!privateDocument && id && oldPack) {
      const old = (await oldPack.getDocuments()).find(d => d.getFlag(NS, "visitId") === id);
      if (old?.getFlag(NS, "sealed")) privateDocument = readOnly?old:await this.createVault(id, old.getFlag(NS, "sealed"));
    }
    const canonical=privateDocument?await this.unseal(privateDocument.getFlag(NS,"sealed"),{readOnly}):null;
    if(this.state?.id!==id)return;
    if(canonical&&canonical.id!==id)throw new Error('Uložená výprava neodpovídá aktuálnímu případu.');
    this.privateDocument=privateDocument;this.canonical=canonical;
    if (!readOnly&&this.canonical && this.isAuthority) await this.ensureActors();
    if (!readOnly&&this.privateDocument && this.isAuthority) await this.publish();
  }
  refreshObserver(){
    if(!game.user.isGM||this.isAuthority||game.pmsAuthority?.failed)return;
    const job=this.queue.then(()=>this.loadPrivate({readOnly:true})).then(()=>this.notify());
    this.queue=job.catch(error=>{this.privateDocument=null;this.canonical=null;ui.notifications.error(error.message);this.notify();});return this.queue;
  }
  documentChanged(doc){
    if(doc.pack)return;
    const type=kind(doc),projection=type==='visitProjection',vault=type==='visitVault'&&doc.getFlag(NS,'visitId')===this.state?.id;
    if(projection||vault)this.refreshObserver();
    if(projection||type==='authorityProof')this.notify();
    if(type==='authorityProof'&&this.isAuthority)for(const user of game.users)this.enqueue(user);
  }
  createVault(visitId, sealed) {
    return JournalEntry.create({ name: "PMS — uložená výprava", ownership: { default: CONST.DOCUMENT_OWNERSHIP_LEVELS.NONE }, flags: { [NS]: { kind: "visitVault", visitId, sealed } } });
  }
  async initialize() {
    if (game.user.isGM&&!game.pmsAuthority?.failed) { try { await this.loadPrivate(); } catch(e) { this.privateDocument=null;this.canonical=null;ui.notifications.error(e.message); } }
    for(const event of ['updateJournalEntry','createJournalEntry','deleteJournalEntry'])Hooks.on(event,doc=>this.documentChanged(doc));
    Hooks.on("updateUser", user => { if (this.isAuthority) this.enqueue(user); this.notify(); });
    Hooks.on("userConnected", () => { if (this.isAuthority) this.queue = this.queue.then(() => this.loadPrivate()).then(() => { for (const u of game.users) this.enqueue(u); }).catch(console.error);else this.refreshObserver(); this.notify(); });
    if (this.isAuthority) for (const u of game.users) this.enqueue(u);
    Hooks.on('pmsAuthorityChanged',()=>{if(this.isAuthority)this.queue=this.queue.then(()=>this.loadPrivate()).then(()=>{for(const u of game.users)this.enqueue(u);}).catch(console.error);else this.refreshObserver();this.notify();});
  }
  enqueue(user) {
    const c = decodeRequest(user.getFlag(NS, "visitRequest"));
    if (!c?.requestId || !this.state || c.visitId !== this.state.id) return;
    this.queue = this.queue.then(() => this.process(c, user)).catch(e => console.error("PMS visit", e));
  }
  async process(command, user) {
    if (!this.isAuthority || !this.privateDocument || !this.privateState || command.visitId !== this.privateState.id) throw new Error("Výprava čeká na svého vypravěče a původní klíč.");
    assertCaseAvailable(this.privateState.caseId);
    if (user.role < CONST.USER_ROLES.PLAYER) throw new Error("Tento uživatel nemůže provádět akce.");
    const result = applyVisitCommand(this.privateState, command, { id: user.id, isGM: user.isGM }, { randomDie });
    // Commit result, deduction, event status and receipt atomically, then publish a recoverable projection.
    if (!result.duplicate) {
      await this.privateDocument.setFlag(NS, "sealed", await this.seal(result.state));
      this.canonical = result.state;
    }
    await this.publish();
    if (result.receipt.ok && command.type === "roll") await this.announceResult(command.actionId);
    this.notify(); return result.receipt;
  }
  async publish() {
    if (this.privateState) await this.syncActors();
    if(this.privateState?.status==='returned'&&this.handleReturn){
      const next=await this.handleReturn(this.privateState);
      if(next!==this.privateState&&!this.privateState.reflectionDiscarded){
        await this.privateDocument.setFlag(NS,'sealed',await this.seal(next));this.canonical=next;
      }
    }
    const visit = publicVisit(this.privateState);
    if (this.document) await this.document.update({flags:{...this.document.flags,[NS]:{...this.document.flags[NS],visit}}},{recursive:false});
    else await JournalEntry.create({ name: "PMS — aktuální výprava", ownership: { default: CONST.DOCUMENT_OWNERSHIP_LEVELS.OBSERVER }, flags: { [NS]: { kind: "visitProjection", visit } } });
    await syncActionMessages(visit,game.messages,(data,avatar)=>ChatMessage.create({...data,speaker:ChatMessage.getSpeaker({actor:game.actors.get(avatar.actorId)})}));
    if(this.privateState?.status==="returned"&&this.onReturnReady)await this.onReturnReady(this.privateState);
  }
  submit(command) {
    const encoded = encodeRequest(command, { requestId: command.requestId ?? foundry.utils.randomID(), visitId: this.state?.id });
    const c = decodeRequest(encoded);
    const run = async () => {
      if (!this.authority || !this.state) throw new Error("Výprava čeká na připojeného vypravěče.");
      if (game.user.isGM && !this.isAuthority) throw new Error("Tento prototyp řídí jeden hlavní vypravěč v původním profilu prohlížeče.");
      if (this.isAuthority) {
        const job = this.queue.then(() => this.process(c, game.user)); this.queue = job.catch(() => {});
        const receipt = await job; if (!receipt.ok) throw new Error(receipt.message); return receipt;
      }
      const confirmation = new Promise((resolve, reject) => {
        const timer = setTimeout(() => { this.pending.delete(c.requestId); reject(new Error("Potvrzení ještě nedorazilo. Čekající akce se může dokončit po návratu vypravěče.")); }, 20000);
        this.pending.set(c.requestId, { resolve, reject, timer });
      });
      confirmation.catch(() => {});
      // A string is replaced atomically; an object flag would recursively retain fields from earlier requests.
      try { await game.user.setFlag(NS, "visitRequest", encoded); this.notify(); return await confirmation; }
      catch (e) { const p = this.pending.get(c.requestId); if (p) { clearTimeout(p.timer); this.pending.delete(c.requestId); p.reject(e); } throw e; }
    };
    const job = this.localQueue.then(run); this.localQueue = job.catch(() => {}); return job;
  }
  async create({ title, start, end, avatars, events = [], world = {}, caseId = "", mode='real', preparationId='' }) {
    if (!this.isAuthority) throw new Error("Výpravu zakládá připojený hlavní vypravěč.");
    if (this.state?.status === "active") throw new Error("Nejdřív dokončete aktuální výpravu.");
    const state = createVisit({ id: foundry.utils.randomID(), title, start, end, avatars, events, world, caseId, mode, preparationId });
    this.privateDocument = await this.createVault(state.id, await this.seal(state));
    this.canonical = state;
    await this.ensureActors();
    await this.publish(); this.notify();
  }
  async ensureActors() {
    let changed = false;
    for (const a of this.canonical.avatars) {
      let actor = game.actors.get(a.actorId) ?? game.actors.find(d=>d.getFlag(NS,"visitAvatar")===`${this.canonical.id}:${a.id}`);
      if (!actor) actor = await Actor.create({ ...(a.actorId?{_id:a.actorId}:{}),name:a.name, type:"avatar", img:a.name.startsWith("Adam")?"systems/pms/assets/adam-portrait.png":"systems/pms/assets/avatar.svg", ownership:{default:0,[a.ownerId]:3}, system:{vitals:a.vitals,skills:a.skills,alive:a.alive,food:a.food,role:a.name.split("·")[1]?.trim()??""}, prototypeToken:{actorLink:true,disposition:1,sight:{enabled:true,range:0,angle:360,visionMode:"basic"}}, flags:{[NS]:{visitAvatar:`${this.canonical.id}:${a.id}`}} },{keepId:true});
      if (!actor.prototypeToken.sight.enabled) await actor.update({"prototypeToken.sight.enabled":true});
      if (a.actorId !== actor.id) { a.actorId=actor.id; changed=true; }
      const user=game.users.get(a.ownerId);
      if (user && (!user.character || user.character.type === "avatar") && user.character?.id !== actor.id) await user.update({character:actor.id});
    }
    if (changed) await this.privateDocument.setFlag(NS,"sealed",await this.seal(this.canonical));
  }
  markLaunchReady(){const job=this.queue.then(()=>this.completeLaunchReady());this.queue=job.catch(()=>{});return job;}
  async completeLaunchReady(){if(!this.isAuthority||!this.privateState)throw new Error('Odjezd dokončuje vypravěč.');
      this.canonical={...this.privateState,launchReady:true};
      await this.privateDocument.setFlag(NS,'sealed',await this.seal(this.canonical));await this.publish();this.notify();
  }
  async syncActors() {
    for (const a of this.canonical.avatars) {
      const actor=game.actors.get(a.actorId); if(!actor)continue;
      const values={vitals:a.vitals,skills:a.skills,alive:a.alive,food:a.food};
      if(Object.entries(values).some(([k,v])=>JSON.stringify(actor.system[k])!==JSON.stringify(v))) await actor.update(Object.fromEntries(Object.entries(values).map(([k,v])=>[`system.${k}`,v])));
      const food=foodInventoryUpdates(actor.items??[],a.food);
      if(food.length)await actor.updateEmbeddedDocuments('Item',food);
    }
    await syncSoulTokens(this.canonical,{actors:game.actors,scenes:game.scenes??[]});
  }
  async announceResult(actionId) {
    const a=this.canonical.actions.find(x=>x.id===actionId), av=this.canonical.avatars.find(x=>x.id===a?.avatarId);
    if (!a?.result || game.messages.some(m=>m.getFlag(NS,"actionResult")===`${this.canonical.id}:${actionId}`))return;
    const esc=foundry.utils.escapeHTML;
    const names={full:"Plný úspěch",partial:"Částečný úspěch",failure:"Neúspěch"};
    const roll=Roll.fromData({class:"Roll",formula:`${a.result.diceCount}d6`,terms:[{class:"Die",number:a.result.diceCount,faces:6,results:a.result.dice.map(n=>({result:n,active:true})),options:{}}],total:a.result.dice.reduce((n,d)=>n+d,0),evaluated:true,options:{}});
    await ChatMessage.create({speaker:ChatMessage.getSpeaker({actor:game.actors.get(av.actorId)}),content:`<div class="pms-chat-result"><h3>${esc(a.title)}</h3><strong>${names[a.result.category]}</strong><div class="pms-dice-faces">${a.result.dice.map(n=>`<span class="${n>=5?"success":""}">${n}</span>`).join("")}</div><p>${a.result.successes} úspěchů / potřeba ${a.required} · tolerance ${a.tolerance}</p></div>`,rolls:[roll],flags:{[NS]:{actionResult:`${this.canonical.id}:${actionId}`}}});
  }
  async key() {
    if (!game.user.isGM) throw new Error("Klíč výpravy patří vypravěči.");
    let hex = game.settings.get(NS, "visitKey");
    if (!hex) { hex = Array.from(crypto.getRandomValues(new Uint8Array(32)), n => n.toString(16).padStart(2, "0")).join(""); await game.settings.set(NS, "visitKey", hex); }
    return hex;
  }
  async seal(state) {
    return sealVisit(state, await this.key());
  }
  async unseal(sealed,{readOnly=false}={}) {
    try {
      return await unsealVisit(sealed,readOnly?game.settings.get(NS,"visitKey"):await this.key());
    } catch { throw new Error("Výpravu lze řídit v původním profilu prohlížeče vypravěče. V tomto profilu chybí její klíč. Nemažte data prohlížeče; přenos klíče zatím prototyp nepodporuje."); }
  }
  async demo() {
    const players = game.users.filter(u => !u.isGM && u.role >= CONST.USER_ROLES.PLAYER).slice(0, 2);
    if (!players.length) throw new Error("Nejdřív vytvořte alespoň jednoho hráče v nastavení Foundry.");
    await this.create({ title: "Havraní zákrut · zkušební výprava", start: 480, end: 1200,
      avatars: players.map((u, i) => ({ id: foundry.utils.randomID(), ownerId: u.id, name: i ? "Nela · svědkyně" : "Adam · stopař", vitals: { vitality: 8, agility: 6, intelligence: 5 }, skills: { analysis: 1, perception: 1, movement: i ? 1 : 0 }, food: 2 })),
      events: [
        { id: "window", title: "Balík z okna", description: "Z okna strážnice letí balík. Někdo uvnitř chce zahladit stopy.", at: 487, location: "Strážnice u zákrutu", visibility: "ask", canReact: true, changes: { parcelOutside: true }, trace: "Roztržený obal pod oknem", witnesses: "Hlídačka zahlédla otevřené okno." },
        { id: "quarrel", title: "Hádka v hostinci", description: "Kurýr prozradí jméno zadavatele, hostinský si je zapamatuje.", at: 489, visibility: "hidden", changes: { innkeeperKnows: true }, witnesses: "Hostinský, dva štamgasti", trace: "Rozbitý džbán" }
      ] });
    for (const [i, a] of this.state.avatars.entries()) await this.submit({ type: "offer", actionId: foundry.utils.randomID(), avatarId: a.id, title: i ? "Rozhovor s hlídačkou" : "Prohlídka řemenu", goal: i ? "Zjistit, kdo projel kolem." : "Hledat způsob poškození řemenu.", kind: i ? "auto" : "risk", duration: i ? 6 : 10, difficulty: 6, required: 4, tolerance: 1, skills: ["analysis"], caps: { vitality: 0, agility: 1, intelligence: 3 }, stakes: "Výsledek popíše vypravěč; samotný hod nerozluští případ." });
  }
}
